// JavaScript writes: nb.set(name, value) puts a copy of the value into nb.
const basket = [
  { item: 'Sourdough loaf', price: 3.20, qty: 1, aisle: 'Bakery' },
  { item: 'Strawberries', price: 2.50, qty: 2, aisle: 'Fruit & veg' },
  { item: 'Cheddar', price: 4.10, qty: 1, aisle: 'Dairy' },
  { item: 'Lemonade', price: 1.80, qty: 3, aisle: 'Drinks' },
  { item: 'Crisps', price: 1.25, qty: 4, aisle: 'Snacks' },
  { item: 'Picnic blanket', price: 12.00, qty: 1, aisle: 'Home' },
];
nb.set('basket', basket);

return `Put ${basket.length} lines into nb.basket`;

// A JavaScript cell can return a Vega-Lite chart. Building it from nb means
// the chart follows the data: change the basket, re-run, and the bars change.
const byAisle = nb.get('by_aisle') ?? {};

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: 'Spend by aisle (from Python\'s nb.by_aisle)',
  width: 520,
  height: 190,
  data: { values: Object.entries(byAisle).map(([aisle, spend]) => ({ aisle, spend })) },
  mark: { type: 'bar', cornerRadiusEnd: 4 },
  encoding: {
    y: { field: 'aisle', type: 'nominal', sort: '-x', title: null },
    x: { field: 'spend', type: 'quantitative', title: 'Spend (£)' },
    color: { field: 'aisle', type: 'nominal', legend: null },
    tooltip: [{ field: 'aisle', title: 'Aisle' }, { field: 'spend', title: 'Spend (£)', format: '.2f' }],
  },
};

// nb hands out copies, not links. Changing what nb.get gave you changes nothing shared...
const basket = nb.get('basket');
basket.push({ item: 'Umbrella', price: 6.50, qty: 1, aisle: 'Home' });

console.log(`This cell's copy: ${basket.length} lines`);
console.log(`Shared nb.basket: ${nb.get('basket').length} lines`);

// ...until you nb.set it back. "Try this" at the end of the notebook shows how.

from itertools import combinations

BUDGET = 30.00
DELIVERY = 3.99

basket = nb.get("basket", [])
if not basket:
    raise RuntimeError("No basket yet. Run the JavaScript basket cell at the top first.")

discount_pct = float(nb.get("discount_pct", 0))
delivery = DELIVERY if nb.get("delivery", False) else 0.0

def total_for(lines):
    subtotal = sum(row["price"] * row["qty"] for row in lines)
    return round(subtotal * (1 - discount_pct / 100) + delivery, 2)

def line_cost(row):
    return row["price"] * row["qty"]

now = total_for(basket)
print(f"Total with {discount_pct:g}% off{' and delivery' if delivery else ''}: £{now:.2f} (budget £{BUDGET:.2f})")

plan = None
if now <= BUDGET:
    print("That's within budget, so nothing needs to go.")
    plan = {"budget": BUDGET, "total": now, "remove": [], "new_total": now}
else:
    # Try removing 1 line, then 2, and so on. The first size that works is the
    # fewest lines; among those, keep the most spend in the basket.
    for count in range(1, len(basket) + 1):
        options = [combo for combo in combinations(basket, count)
                   if total_for([row for row in basket if row not in combo]) <= BUDGET]
        if options:
            best = min(options, key=lambda combo: sum(line_cost(row) for row in combo))
            kept = [row for row in basket if row not in best]
            new_total = total_for(kept)
            names = [row["item"] for row in best]
            print(f"Over by £{now - BUDGET:.2f}. Fewest lines to drop: {count}.")
            for row in best:
                print(f"  drop {row['qty']} × {row['item']} (£{line_cost(row):.2f} before discount)")
            print(f"New total: £{new_total:.2f}")
            plan = {"budget": BUDGET, "total": now, "remove": names, "new_total": new_total}
            break
    if plan is None:
        print("Even an empty basket is over budget, because of delivery.")
        plan = {"budget": BUDGET, "total": now, "remove": [row["item"] for row in basket], "new_total": total_for([])}

nb["budget_plan"] = plan
